import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"思美人","description":"","frontmatter":{"title":"思美人","date":"2026-11-24T00:00:00.000Z","seq":19,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"屈原","source_book":"楚辞","prev":{"text":"怀沙","link":"/blogs/楚辞/怀沙.html"},"next":{"text":"惜往日","link":"/blogs/楚辞/惜往日.html"}},"headers":[],"relativePath":"blogs/楚辞/思美人.md","filePath":"blogs/楚辞/思美人.md"}'),o={name:"blogs/楚辞/思美人.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="思美人" tabindex="-1">思美人 <a class="header-anchor" href="#思美人" aria-label="Permalink to &quot;思美人&quot;">​</a></h1><p class="poem-meta">先秦 · 屈原　·　九章</p><div class="poem"><p class="poem-stanza">思美人兮，揽涕而竚眙。</p><p class="poem-stanza">媒绝路阻兮，言不可结而诒。</p><p class="poem-stanza">蹇蹇之烦冤兮，陷滞而不发。</p><p class="poem-stanza">申旦以舒中情兮，志沉菀而莫达。</p><p class="poem-stanza">愿寄言于浮云兮，遇丰隆而不将。</p><p class="poem-stanza">因归鸟而致辞兮，羌迅高而难当。</p><p class="poem-stanza">高辛之灵盛兮，遭玄鸟而致诒。</p><p class="poem-stanza">欲变节以从俗兮，媿易初而屈志。</p><p class="poem-stanza">独历年而离愍兮，羌凭心犹未化。</p><p class="poem-stanza">宁隐闵而寿考兮，何变易之可为！</p><p class="poem-stanza">知前辙之不遂兮，未改此度。</p><p class="poem-stanza">车既覆而马颠兮，蹇独怀此异路。</p><p class="poem-stanza">勒骐骥而更驾兮，造父为我操之，</p><p class="poem-stanza">迁逡次而勿驱兮，聊假日以须是时。</p><p class="poem-stanza">指嶓冢之西隈兮，与纁黄以为期。</p><p class="poem-stanza">开春发岁兮，白日出之悠悠。</p><p class="poem-stanza">吾将荡志而愉乐兮，遵江夏以娱忧。</p><p class="poem-stanza">揽大薄之芳茝兮，搴长洲之宿莽。</p><p class="poem-stanza">惜吾不及古人兮，吾谁与玩此芳草？</p><p class="poem-stanza">解萹薄与杂菜兮，备以为交佩。</p><p class="poem-stanza">佩缤纷以缭转兮，遂萎绝而离异。</p><p class="poem-stanza">吾且儃徊以娱忧兮，观南人之变态。</p><p class="poem-stanza">窃快在中心兮，扬厥凭而不竢。</p><p class="poem-stanza">芳与泽其杂糅兮，羌芳华自中出。</p><p class="poem-stanza">纷郁郁其远蒸兮，满内而外扬。</p><p class="poem-stanza">情与质信可保兮，羌居蔽而闻章。</p><p class="poem-stanza">令薜荔以为理兮，惮举趾而缘木。</p><p class="poem-stanza">因芙蓉而为媒兮，惮褰裳而濡足。</p><p class="poem-stanza">登高吾不说兮，入下吾不能。</p><p class="poem-stanza">固朕形之不服兮，然容与而狐疑。</p><p class="poem-stanza">广遂前画兮，未改此度也。</p><p class="poem-stanza">命则处幽吾将罢兮，愿及白日之未暮也。</p><p class="poem-stanza">独茕茕而南行兮，思彭咸之故也。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
